import jax
import jax.numpy as jnp
import flax.linen as nn
import optax
from typing import Dict, Any, Sequence

# --- Hyperparameters ---
def _define_hyperparameters():
    return {
        'peak_learning_rate': 0.001, 'total_train_steps': 200000, 'warmup_steps': 2000,
        'hidden_dim': 512, 'dropout_rate': 0.1,
        'cnn_kernel_sizes': [3, 5, 7],
        'sgrna_len': 20 # Based on CRI-Off description, target is 23nt, sgRNA should be 20nt
    }
# Note: CRI-Off description says sgRNA + target concat, seq len 43. sgRNA is typically 20nt, target site 23nt.

# --- Optimizer ---
def create_optimizer(learning_rate: float = 0.001):
    hparams = _define_hyperparameters()
    lr_schedule = optax.warmup_cosine_decay_schedule(
        init_value=0.0, peak_value=hparams.get('peak_learning_rate', learning_rate),
        warmup_steps=hparams.get('warmup_steps'), decay_steps=hparams.get('total_train_steps'))
    return optax.adamw(learning_rate=lr_schedule, weight_decay=0.01)

# --- Shared Components ---
class Bidirectional(nn.Module):
    hidden_size: int
    @nn.compact
    def __call__(self, xs):
        forward_lstm = nn.RNN(nn.LSTMCell(features=self.hidden_size), name="forward")
        forward_output = forward_lstm(xs)
        reversed_xs = jnp.flip(xs, axis=1)
        backward_lstm = nn.RNN(nn.LSTMCell(features=self.hidden_size), name="backward")
        backward_output = jnp.flip(backward_lstm(reversed_xs), axis=1)
        return jnp.concatenate([forward_output, backward_output], axis=-1)

class Attention(nn.Module):
    @nn.compact
    def __call__(self, x):
        weights = nn.Dense(features=x.shape[-1])(x)
        weights = nn.tanh(weights)
        weights = nn.Dense(features=1)(weights)
        weights = nn.softmax(weights, axis=1)
        return jnp.sum(x * weights, axis=1)

# --- Model 1: Siamese Network (for CRI-Off) ---
class SiameseEncoder(nn.Module):
    num_filters: int; cnn_kernel_sizes: Sequence[int]; lstm_hidden_size: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        cnn_outputs = [nn.Conv(features=self.num_filters, kernel_size=(ks,))(x) for ks in self.cnn_kernel_sizes]
        x = jnp.concatenate(cnn_outputs, axis=-1)
        x = nn.relu(x)
        x = Bidirectional(hidden_size=self.lstm_hidden_size)(x)
        x = Attention()(x)
        return x

class SiameseModel(nn.Module):
    hparams: Dict[str, Any]
    @nn.compact
    def __call__(self, x, deterministic=True):
        sgrna_len = self.hparams.get('sgrna_len')
        sgrna_x = x[:, :sgrna_len, :]
        target_x = x[:, sgrna_len:, :]

        encoder = SiameseEncoder(
            num_filters=self.hparams.get('hidden_dim') // len(self.hparams.get('cnn_kernel_sizes')),
            cnn_kernel_sizes=self.hparams.get('cnn_kernel_sizes'),
            lstm_hidden_size=self.hparams.get('hidden_dim') // 2,
            dropout_rate=self.hparams.get('dropout_rate')
        )
        sgrna_vec = encoder(sgrna_x, deterministic=deterministic)
        target_vec = encoder(target_x, deterministic=deterministic)

        interaction_diff = jnp.abs(sgrna_vec - target_vec)
        interaction_prod = sgrna_vec * target_vec

        combined_vec = jnp.concatenate([sgrna_vec, target_vec, interaction_diff, interaction_prod], axis=-1)

        x = nn.Dropout(rate=self.hparams.get('dropout_rate'))(combined_vec, deterministic=deterministic)
        x = nn.Dense(features=self.hparams.get('hidden_dim'))(x)
        x = nn.relu(x)
        x = nn.Dense(features=1)(x)
        return x.squeeze(-1)

# --- Model 2: Advanced Seq Model (for other tasks) ---
class AdvancedModel(nn.Module):
    hparams: Dict[str, Any]
    @nn.compact
    def __call__(self, x, deterministic=True):
        num_kernels = len(self.hparams.get('cnn_kernel_sizes'))
        num_filters = self.hparams.get('hidden_dim') // num_kernels
        cnn_outputs = [nn.Conv(features=num_filters, kernel_size=(ks,))(x) for ks in self.hparams.get('cnn_kernel_sizes')]
        x = jnp.concatenate(cnn_outputs, axis=-1)
        x = nn.relu(x)
        x = Bidirectional(hidden_size=self.hparams.get('hidden_dim') // 2)(x)
        x = Attention()(x)
        x = nn.Dropout(rate=self.hparams.get('dropout_rate'))(x, deterministic=deterministic)
        x = nn.Dense(features=self.hparams.get('d_output'))(x)
        if self.hparams.get('task_type') == "regression": return x.squeeze(-1)
        else: return x

# --- Universal Wrapper and Conditional Logic ---
class NetworkWrapper:
    def __init__(self, network_module): self.network = network_module
    def init(self, rng_key, dummy_input):
        params_key, dropout_key = jax.random.split(rng_key)
        return self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        rngs = {'dropout': rng_key if rng_key is not None else jax.random.PRNGKey(0)}
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs=rngs)

def create_network(hparams: Dict[str, Any]):
    if hparams.get("dataset") == "CRI-Off":
        module = SiameseModel(hparams=hparams)
    else:
        hparams['d_output'] = hparams.get('d_output') # ensure d_output is available
        hparams['task_type'] = hparams.get('task_type')
        module = AdvancedModel(hparams=hparams)
    return NetworkWrapper(module)
